{
  "passageId": "modern-civilization-science-ga",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "척사파의 반대가 지속되었는데도 개화가 대세로 자리 잡았다는 양보 관계이다."
    },
    {
      "id": "R2",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "개항을 기점으로 개화의 의미가 전통적 통치 행위에서 서양 문명 수용으로 변하는 시대적 전개를 보여 준다."
    },
    {
      "id": "R3",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "서양 문명에 대한 긍정적 인식의 확산이 새로운 개화 개념이 정착하는 사상적 배경이다."
    },
    {
      "id": "R4",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "서양 문물 수용에 반대하는 척사파의 입장과 이를 긍정적으로 보는 입장이 나란히 제시된다."
    },
    {
      "id": "R5",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "고종의 자강 정책 추진은 반서양 정서를 교정하려는 신문 발간의 정책적 배경이다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "『한성순보』의 발간을 소개한 뒤 그 신문이 제시한 개화 개념의 내용을 자세히 설명한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "독립 주권의 소중함을 깨닫는 의식 변화는 인지의 발달에 담긴 구체적인 내용을 풀어 준다."
    },
    {
      "id": "R8",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "『한성순보』와 개화당 인사가 개화를 각각 통치자 중심의 국가 진보와 서양식 통치 절차의 실현으로 이해하는 관점 차이를 보여 준다."
    },
    {
      "id": "R9",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "왕을 실행 주체로 보던 단계에서 갑신정변을 계기로 왕의 역할이 사라지는 단계로 개화 논의가 전개된다."
    },
    {
      "id": "R10",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "두 개화 개념이 모두 통치 방식의 변화라는 내용을 포함한다는 공통점으로 연결된다."
    },
    {
      "id": "R11",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "『한성순보』와 갑신정변의 개화 개념이 풍속의 진보라는 공통된 의미 요소를 가진다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "개화가 통치권 도전과 사욕으로 표상되었다는 사실이 부정적 이미지에서 벗어나야 한다는 당위의 근거이다."
    },
    {
      "id": "R13",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "개화의 부정적 이미지를 해소해야 한다는 과제에 대응하여 유길준이 『서유견문』을 저술했다."
    },
    {
      "id": "R14",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "국가 구성원의 조직과 동원을 위해 이미지 개선이 요구되던 단계에서 조직과 동원 자체가 개화의 의미로 제시되는 단계로 나아간다."
    },
    {
      "id": "R15",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "개화 실행 주체를 왕으로 보는 개화당 인사의 견해와 국가 구성원 전체로 보는 신문들의 견해가 다르다."
    },
    {
      "id": "R16",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "두 개화 개념의 내용이 각각 의식 변화와 조직·동원이라는 서로 다른 활동을 국가 주권과 연결한다는 공통점을 가진다."
    },
    {
      "id": "R17",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "개화의 의미와 실행 주체에 관한 논의에서 을사늑약 이후의 본격적인 문명 논의로 화제가 확대된다."
    },
    {
      "id": "R18",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "일본의 지도를 받는 것은 서양 문명을 수용하여 근대 국가를 건설하려는 목적을 위한 수단으로 제시된다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "일본이 먼저 문명화를 이루었다는 사실이 일본의 지도를 받아야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "서양 근대 문명의 주체를 인식의 준거로 삼은 것이 민족 주체성을 간과하는 결과로 이어졌다."
    },
    {
      "id": "R21",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "서양 문명의 주체를 준거로 삼은 대한 자강회 인사들과 유학의 혁신을 통해 새로운 주체를 구상한 박은식의 관점이 구별된다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "문명 요소의 확보 방식이라는 기준에서 과학은 서양으로부터 수용하고 철학은 유학을 혁신하여 재구성한다는 차이가 있다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생존과 편리를 위한 과학 연구의 시급성이 서양 과학을 수용하는 전략의 필요성을 뒷받침한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "가치관 정립과 인격 수양에 철학이 필수적이라는 판단이 철학을 재구성하는 전략의 필요성을 뒷받침한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "과학 연구의 시급성을 인정하면서도 그것만으로 충분하지 않으며 철학 또한 필수적이라는 한계를 제시한다."
    },
    {
      "id": "R26",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "과학 수용과 철학 재구성이라는 문명 수용 전략에서 이를 담당할 근대 주체의 성격에 관한 논의로 나아간다."
    },
    {
      "id": "R27",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "자국 철학 전통을 정립하려는 동아시아의 사상적 흐름이 박은식의 유학 혁신과 철학 재구성 전략의 배경이다."
    }
  ]
}

